def decode_string(s):
    stack = []
    cur = []
    num = 0
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == '[':
            stack.append((cur, num))
            cur, num = [], 0
        elif ch == ']':
            prev, k = stack.pop()
            prev.append(''.join(cur) * k)
            cur = prev
        else:
            cur.append(ch)
    return ''.join(cur)

solution.javascript:
function decodeString(s) {
  const stack = []
  let cur = [], num = 0
  for (const ch of s) {
    if (ch >= '0' && ch <= '9') num = num * 10 + (ch.charCodeAt(0) - 48)
    else if (ch === '[') { stack.push([cur, num]); cur = []; num = 0 }
    else if (ch === ']') { const [prev, k] = stack.pop(); prev.push(cur.join('').repeat(k)); cur = prev }
    else cur.push(ch)
  }
  return cur.join('')
}

