from collections import OrderedDict

def lru_cache(capacity, operations):
    cache = OrderedDict()
    out = []
    for op in operations:
        key = op[1]
        if op[0] == 0:
            if key in cache:
                cache.move_to_end(key)
                out.append(cache[key])
            else:
                out.append(-1)
        else:
            if key in cache:
                cache.move_to_end(key)
            cache[key] = op[2]
            if len(cache) > capacity:
                cache.popitem(last=False)
    return out

