import heapq

def median_sliding_window(nums, k):
    if not nums or k <= 0 or k > len(nums):
        return []
    lower = []                 # max-heap encoded as negative values
    upper = []                 # min-heap
    delayed = {}
    lower_size = upper_size = 0

    def prune(heap, sign):
        while heap:
            value = sign * heap[0]
            count = delayed.get(value, 0)
            if count == 0:
                break
            heapq.heappop(heap)
            if count == 1:
                del delayed[value]
            else:
                delayed[value] = count - 1

    def rebalance():
        nonlocal lower_size, upper_size
        prune(lower, -1)
        prune(upper, 1)
        if lower_size > upper_size + 1:
            value = -heapq.heappop(lower)
            lower_size -= 1
            heapq.heappush(upper, value)
            upper_size += 1
            prune(lower, -1)
        elif lower_size < upper_size:
            value = heapq.heappop(upper)
            upper_size -= 1
            heapq.heappush(lower, -value)
            lower_size += 1
            prune(upper, 1)

    def add(value):
        nonlocal lower_size, upper_size
        prune(lower, -1)
        if not lower or value <= -lower[0]:
            heapq.heappush(lower, -value)
            lower_size += 1
        else:
            heapq.heappush(upper, value)
            upper_size += 1
        rebalance()

    def remove(value):
        nonlocal lower_size, upper_size
        prune(lower, -1)
        prune(upper, 1)
        delayed[value] = delayed.get(value, 0) + 1
        if value <= -lower[0]:
            lower_size -= 1
            if value == -lower[0]:
                prune(lower, -1)
        else:
            upper_size -= 1
            if upper and value == upper[0]:
                prune(upper, 1)
        rebalance()

    def median():
        prune(lower, -1)
        prune(upper, 1)
        if k % 2:
            return float(-lower[0])
        return (-lower[0] + upper[0]) / 2.0

    result = []
    for i, value in enumerate(nums):
        add(value)
        if i >= k:
            remove(nums[i - k])
        if i >= k - 1:
            result.append(median())
    return result

