            if i in (0, m - 1) or j in (0, n - 1):
                heapq.heappush(heap, (height_map[i][j], i, j))
                seen[i][j] = True
    water = 0
    while heap:
        h, i, j = heapq.heappop(heap)
        for x, y in ((i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)):
            if 0 <= x < m and 0 <= y < n and not seen[x][y]:
                seen[x][y] = True
                cell = height_map[x][y]
                if cell < h:
                    water += h - cell
                heapq.heappush(heap, (max(h, cell), x, y))
