def ladder_length(begin_word, end_word, word_list):
    words = set(word_list)
    if end_word not in words:
        return 0
    L = len(begin_word)
    buckets = defaultdict(list)
    for w in words:
        for i in range(L):
            buckets[w[:i] + '*' + w[i + 1:]].append(w)
    seen = {begin_word}
    q = deque([(begin_word, 1)])
    while q:
        w, d = q.popleft()
        for i in range(L):
            key = w[:i] + '*' + w[i + 1:]
            for nxt in buckets.get(key, ()):
                if nxt == end_word:
                    return d + 1
                if nxt not in seen:
                    seen.add(nxt)
                    q.append((nxt, d + 1))
            buckets[key] = []
    return 0

