solution.python:
def find_ladders(begin_word, end_word, word_list):
    if begin_word == end_word:
        return [[begin_word]]
    words = set(word_list)
    if end_word not in words:
        return []
    words.discard(begin_word)
    parents = {}
    frontier = {begin_word}
    found = False
    alphabet = 'abcdefghijklmnopqrstuvwxyz'
    while frontier and not found:
        next_frontier = set()
        for word in frontier:
            chars = list(word)
            for i, original in enumerate(chars):
                for letter in alphabet:
                    if letter == original:
                        continue
                    chars[i] = letter
                    candidate = ''.join(chars)
                    if candidate in words:
                        next_frontier.add(candidate)
                        parents.setdefault(candidate, []).append(word)
                chars[i] = original
        words.difference_update(next_frontier)
        if end_word in next_frontier:
            found = True
        frontier = next_frontier
    if not found:
        return []
    result = []
    path = [end_word]
    def build(word):
        if word == begin_word:
            result.append(path[::-1])
            return
        for previous in sorted(parents.get(word, [])):
            path.append(previous)
            build(previous)
            path.pop()
    build(end_word)
    return result

